#[cfg(any(feature = "gurobi10", feature = "gurobi11", feature = "gurobi12"))]
#[test]
fn iis_job_returns_a_real_subsystem_through_the_shared_lifecycle() {
    let engine = NativeEngine::default();
    let view = engine.submit(infeasible_request()).unwrap();
    // 同一进程内同步完成；轮询到终态而不是假设立即完成。
    // It completes synchronously in-process, but poll for a terminal state instead of assuming.
    let finished = std::iter::repeat_with(|| { std::thread::sleep(std::time::Duration::from_millis(20)); engine.get(&view.id).unwrap() })
        .take(500).find(|job| job.status != JobStatus::Running).expect("IIS job never reached a terminal state");
    assert_eq!(finished.status, JobStatus::Completed, "{:?}", finished.error);
    let report: ospf_rust_bridge::LinearIisReport = serde_json::from_str(finished.report_json.as_deref().unwrap()).unwrap();
    assert_eq!(report.algorithm, LinearIisAlgorithm::Elastic);
    assert_eq!(report.original_constraint_count, 2);
    assert_eq!(report.constraint_ids.len(), 2);
    assert!(report.constraint_ids[0].contains("at_least_five"));
    assert!(report.constraint_ids[1].contains("at_most_one"));
    engine.release(&view.id).unwrap();
}
